	constexpr auto operator||(opsy::utility::clear_set<tim1_cr1_r> other) const -> opsy::utility::clear_set<tim1_cr1_r> {return opsy::utility::clear_set<tim1_cr1_r>(tim1_cr1_r(mask) | other.clear(), *this | other.set()); }

