/**
 * Index positioning In quadrature encoder mode (SMS[3:0] = 0001, 0010, 0011, 1110, 1111), this bit indicates in which AB input configuration the Index event resets the counter. In directional clock mode or clock plus direction mode (SMS[3:0] = 1010, 1011, 1100, 1101), these bits indicates on which level the Index event resets the counter. In bidirectional clock mode, this applies for both clock inputs. x0: Index resets the counter when clock is 0 x1: Index resets the counter when clock is 1 Note: IPOS[1] bit is not significant
 */
class ipos_f {
public:
	static constexpr std::size_t offset = 6;
	static constexpr std::size_t width = 2;
	static constexpr uint8_t range = static_cast<uint8_t>(0b11);
	static constexpr uint8_t mask = static_cast<uint8_t>(static_cast<uint8_t>(range) << offset);

	constexpr ipos_f(uint8_t value) : value_(value & range) {}
	constexpr operator uint8_t() const {return value_;}
	constexpr operator tim1_ecr_r() const {return static_cast<uint8_t>(static_cast<uint8_t>(value_) << offset);}
	constexpr operator opsy::utility::clear_set<tim1_ecr_r>() const {return opsy::utility::clear_set<tim1_ecr_r>(mask, *this);}
	constexpr auto operator|(tim1_ecr_r other) const -> tim1_ecr_r { return static_cast<tim1_ecr_r>(*this) | other.value_;}
	constexpr auto operator||(opsy::utility::clear_set<tim1_ecr_r> other) const -> opsy::utility::clear_set<tim1_ecr_r> {return opsy::utility::clear_set<tim1_ecr_r>(tim1_ecr_r(mask) | other.clear(), *this | other.set()); }

private:
	 uint8_t value_;
};

/**
 * Pulse width This bitfield defines the pulse duration, as following: tsub PW/sub = PW[7:0] x tsub PWG/sub 
 */
