	constexpr operator opsy::utility::clear_set<tim3_ccmr1_output_r>() const {return opsy::utility::clear_set<tim3_ccmr1_output_r>(mask, *this);}
	constexpr auto operator|(tim3_ccmr1_output_r other) const -> tim3_ccmr1_output_r { return static_cast<tim3_ccmr1_output_r>(*this) | other.value_;}
