	constexpr auto operator|(tim8_ccr1_r other) const -> tim8_ccr1_r { return static_cast<tim8_ccr1_r>(*this) | other.value_;}
	constexpr auto operator||(opsy::utility::clear_set<tim8_ccr1_r> other) const -> opsy::utility::clear_set<tim8_ccr1_r> {return opsy::utility::clear_set<tim8_ccr1_r>(tim8_ccr1_r(mask) | other.clear(), *this | other.set()); }

private:
	 uint32_t value_;
