	constexpr auto operator||(opsy::utility::clear_set<tim15_ccr1_r> other) const -> opsy::utility::clear_set<tim15_ccr1_r> {return opsy::utility::clear_set<tim15_ccr1_r>(tim15_ccr1_r(mask) | other.clear(), *this | other.set()); }

private:
