	constexpr auto operator||(opsy::utility::clear_set<tim15_dtr2_r> other) const -> opsy::utility::clear_set<tim15_dtr2_r> {return opsy::utility::clear_set<tim15_dtr2_r>(tim15_dtr2_r(mask) | other.clear(), *this | other.set()); }

private:
